template <typename Key>
struct RBNode {
    Key value;
    bool is_red = true; // Red-Black Tree property
    RBNode* parent = nullptr;
    RBNode* left = nullptr;
    RBNode* right = nullptr;
};

// Internal implementation of std::set
template <typename Key, typename Comp>
class SetImpl {
    using Node = RBNode<Key>;
    Node* root;
    Node* sentinel; // Header node, acts as 'end()'
    Comp comparator;

    // Guaranteed O(log N) time complexity
    void insert(const Key& k);
    void rotate_left(Node* n); // Balancing operation
    // Tree traversal uses comparator
};
